# Grid lambda consumes META so autotune tile choices take effect
@triton.autotune(configs=[Config({'XBLOCK':1024,'YBLOCK':1},...), ...], key=[...])
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK: tl.constexpr, XBLOCK: tl.constexpr):
    ...

# FIXED: lambda reads META so each autotune config gets the correct grid
grid = lambda META: (
    triton.cdiv(xnumel, META['XBLOCK']),
    triton.cdiv(ynumel, META['YBLOCK']),
)
# Do NOT pass XBLOCK/YBLOCK as explicit kwargs — autotune injects via META
kernel[grid](in_ptr, out_ptr, ynumel, xnumel)
